import sys,json,subprocess,time,hashlib,os,tempfile,re
from pathlib import Path
ROOT=Path(__file__).resolve().parent
OWNED=['rust/Cargo.lock','rust/crates/lingxi-adapters/Cargo.toml','rust/crates/lingxi-adapters/src/storage/agent_config.rs','rust/crates/lingxi-adapters/src/storage/agent_memory.rs','rust/crates/lingxi-adapters/src/storage/skill_library.rs','rust/crates/lingxi-service/src/context_compiler.rs','rust/crates/lingxi-service/src/memory.rs','rust/crates/lingxi-service/src/memorytools.rs','rust/crates/lingxi-service/src/persona.rs','rust/crates/lingxi-service/src/skills.rs','rust/crates/lingxi-service/tests/r06_t01_context_compiler.rs','rust/crates/lingxi-adapters/tests/agent_memory_r06t06.rs','rust/crates/lingxi-service/tests/r06_ar_f06_config.rs','rust/crates/lingxi-service/tests/r06_ar_f06_binary.rs','rust/crates/lingxi-adapters/tests/r06_ar_f06_config_preservation.rs']
def digest():return {p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in OWNED}
if __name__=='__main__':
 tag=sys.argv[1];command=sys.argv[2:];environment=os.environ.copy();home=tempfile.mkdtemp(prefix='lingxi-w06-'+tag+'-');environment.update(LINGXI_HOME=home,TEST_GUARD_VERBOSE='1',TEST_MEM_LIMIT_MB='8192',TEST_TIME_LIMIT_SEC='600',LINGXI_TEST_GUARD='1')
 start=time.time();before=digest();target=Path(environment.get('CARGO_TARGET_DIR','rust/target'));binary=target/'debug/lingxi-service';binary_before=hashlib.sha256(binary.read_bytes()).hexdigest() if binary.is_file() else None;log=ROOT/'logs'/f'{tag}.log'
 with log.open('w') as out:
  out.write(json.dumps({'command':command,'start':start,'LINGXI_HOME':home,'guard':'8192MB/600s'},ensure_ascii=False)+'\n');out.flush()
  result=subprocess.run(command,env=environment,stdout=out,stderr=subprocess.STDOUT)
 end=time.time();content=log.read_text();tests=[int(m) for m in re.findall(r'test result: (?:ok|FAILED)\. (\d+) passed',content)];record={'tag':tag,'candidate_sha':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'working_tree_digest':hashlib.sha256(json.dumps(before,sort_keys=True).encode()).hexdigest(),'owned_hashes_before':before,'owned_hashes_after':digest(),'toolchain':'cargo 1.98.1','lock_hash':before['rust/Cargo.lock'],'fixture_hash':before['rust/crates/lingxi-service/tests/r06_ar_f06_binary.rs'],'platform':subprocess.check_output(['uname','-a'],text=True).strip(),'command':command,'start_time':start,'end_time':end,'exit_code':result.returncode,'test_count':sum(tests),'LINGXI_HOME':home,'evidence_hash':hashlib.sha256(log.read_bytes()).hexdigest(),'status':'PASS' if result.returncode==0 else 'FAIL','guard':'8192MB/600s','cwd':str(Path.cwd()),'CARGO_TARGET_DIR':str(target.resolve()),'service_binary_path':str(binary.resolve()),'service_binary_sha256_before':binary_before,'service_binary_sha256_after':hashlib.sha256(binary.read_bytes()).hexdigest() if binary.is_file() else None,'mock_boundary':'仅外部模型端点/应答，生产配置/材料/网关/存储/服务进程不mock'}
 (ROOT/f'{tag}.json').write_text(json.dumps(record,ensure_ascii=False,indent=2))
 print(json.dumps({k:record[k] for k in ['tag','exit_code','test_count','start_time','end_time']},ensure_ascii=False))
 sys.exit(result.returncode)
